def _patch_u32(buf, offset, value):
    """Return a copy of buf with one 32-bit little-endian field changed."""
    out = bytearray(buf)
    out[offset : offset + 4] = pack("<I", value)
    return bytes(out)


def _rewrap_ole(encryption_info):
    """Repackage (possibly mutated) streams into a valid OLE container."""
    with olefile.OleFileIO(io.BytesIO(GOLDEN[128]["ole"])) as src:
        package = src.openstream("EncryptedPackage").read()
    buf = io.BytesIO()
    ECMA376Encrypted(package, encryption_info).write_to(buf)
    return buf.getvalue()


def _mutated_file(field_offset, value, bits=128):
    info = _patch_u32(GOLDEN[bits]["encryption_info"], field_offset, value)
    return _rewrap_ole(info)


class StandardKeyDerivationKAT(unittest.TestCase):
    """Independent known answers for the full Standard key derivation."""

    def test_golden_keys_for_all_aes_lengths(self):
        for bits, golden in GOLDEN.items():
            key = ECMA376Standard.makekey_from_password(
                PASSWORD,
                ALG_IDS[bits],
                ALG_ID_HASH_SHA1,
                PROVIDER_RSA_AES,
                bits,
                SALT_SIZE,
                golden["salt"],
            )
            self.assertEqual(key, golden["key"])
            self.assertEqual(len(key), bits // 8)

    def test_password_encoded_utf16le(self):
        # A UTF-16BE or raw-UTF-8 encoding of the password must derive a
        # different key; this pins the exact password input transformation.
        golden = GOLDEN[128]
        correct = ECMA376Standard.makekey_from_password(
            PASSWORD, ALG_IDS[128], ALG_ID_HASH_SHA1, PROVIDER_RSA_AES,
            128, SALT_SIZE, golden["salt"],
        )

        def wrong_derive(password_bytes):
            h = sha1(golden["salt"] + password_bytes).digest()
            for i in range(50000):
                h = sha1(pack("<I", i) + h).digest()
            hfinal = sha1(h + pack("<I", 0)).digest()
            x1 = sha1(bytearray(a ^ b for a, b in zip(hfinal, b"\x36" * 20)) + b"\x36" * 44).digest()
            x2 = sha1(bytearray(a ^ b for a, b in zip(hfinal, b"\x5c" * 20)) + b"\x5c" * 44).digest()
            return (x1 + x2)[:16]

        self.assertNotEqual(wrong_derive(PASSWORD.encode("utf-8")), correct)
        self.assertNotEqual(wrong_derive(PASSWORD.encode("utf-16be")), correct)
        self.assertEqual(wrong_derive(PASSWORD.encode("utf-16le")), correct)

    def test_iteration_count_is_50000(self):
        # 49999 iterations must not yield the golden key, pinning the
        # Standard-specific spin count (Agile uses a different scheme).
        golden = GOLDEN[128]
        h = sha1(golden["salt"] + PASSWORD.encode("utf-16le")).digest()
        for i in range(49999):
            h = sha1(pack("<I", i) + h).digest()
        hfinal = sha1(h + pack("<I", 0)).digest()
        x1 = sha1(bytearray(a ^ b for a, b in zip(hfinal, b"\x36" * 20)) + b"\x36" * 44).digest()
        x2 = sha1(bytearray(a ^ b for a, b in zip(hfinal, b"\x5c" * 20)) + b"\x5c" * 44).digest()
        self.assertNotEqual((x1 + x2)[:16], golden["key"])

    def test_different_passwords_diverge(self):
        golden = GOLDEN[128]
        other = ECMA376Standard.makekey_from_password(
            "other-password", ALG_IDS[128], ALG_ID_HASH_SHA1, PROVIDER_RSA_AES,
            128, SALT_SIZE, golden["salt"],
        )
        self.assertNotEqual(other, golden["key"])


